package com.repairconnect.entity;
import jakarta.persistence.*;
@Entity @Table(name="service_providers") public class ProviderProfile { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) private User user; private String address; private String city; private Integer experience; @Column(length=2000) private String description; private Double hourlyRate; @Enumerated(EnumType.STRING) private VerificationStatus verificationStatus=VerificationStatus.PENDING; private Double averageRating=0.0; private Integer totalReviews=0; private String profileImage; public ProviderProfile(){} public ProviderProfile(User u,String a,String c,Integer e,String d){user=u;address=a;city=c;experience=e;description=d;} public Long getId(){return id;} public User getUser(){return user;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public Integer getExperience(){return experience;} public String getDescription(){return description;} public Double getHourlyRate(){return hourlyRate;} public void setHourlyRate(Double v){hourlyRate=v;} public VerificationStatus getVerificationStatus(){return verificationStatus;} public void setVerificationStatus(VerificationStatus v){verificationStatus=v;} public Double getAverageRating(){return averageRating;} public void setAverageRating(Double v){averageRating=v;} public Integer getTotalReviews(){return totalReviews;} public void setTotalReviews(Integer v){totalReviews=v;} public String getProfileImage(){return profileImage;} public void setProfileImage(String v){profileImage=v;} }